}

class Bar : Foo() {
    override fun run() {
        window.alert("Running!")
    }

    fun restart() {
        window.alert("Restarting")
    }
}

There are some limitations:

When a function of an external base class is overloaded by signature, you can't override it in a derived class.

You can't override a function including parameters with default values.

Non-external classes can't be extended by external classes.","title":"Use JavaScript code from Kotlin","source":"https://kotlinlang.org/docs/js-interop.html","sections":["Use JavaScript code from Kotlin > external modifier > Extend JavaScript classes"],"line_start":99,"line_end":124,"score":0.669739842414856,"release_version":null,"availability":"unknown"},{"anchor":"external-interfaces","start":2614,"end":2847,"split_code":false,"platforms":["wasm"],"id":"1189f47b823a1c2e9565077478c0d670435c6ed7c235d16bbe737162ce81387b","document_id":"wasm-js-interop","strategy":"semantic","text":"You can't use them on the right-hand side of is checks.

